#!/usr/bin/env bash
# Example Linux configure for a container where GitHub archive downloads are blocked.
# Run from the patched WiiCompiled checkout. DEPS holds git clones of each dependency.
cmake -S runtime -B build-linux -G Ninja -DCMAKE_BUILD_TYPE=Release -DCMAKE_C_COMPILER=clang -DCMAKE_CXX_COMPILER=clang++ -DAURORA_SDL3_PROVIDER=vendor  -DFETCHCONTENT_SOURCE_DIR_ABSEIL-CPP=${DEPS:?set DEPS to your dependency checkout folder}/abseil-cpp -DFETCHCONTENT_SOURCE_DIR_XXHASH=${DEPS:?set DEPS to your dependency checkout folder}/xxhash -DFETCHCONTENT_SOURCE_DIR_FMT=${DEPS:?set DEPS to your dependency checkout folder}/fmt -DFETCHCONTENT_SOURCE_DIR_ZLIB=${DEPS:?set DEPS to your dependency checkout folder}/zlib -DFETCHCONTENT_SOURCE_DIR_PNG=${DEPS:?set DEPS to your dependency checkout folder}/png -DFETCHCONTENT_SOURCE_DIR_TRACY=${DEPS:?set DEPS to your dependency checkout folder}/tracy -DFETCHCONTENT_SOURCE_DIR_SDL=${DEPS:?set DEPS to your dependency checkout folder}/sdl -DFETCHCONTENT_SOURCE_DIR_IMGUI=${DEPS:?set DEPS to your dependency checkout folder}/imgui -DFETCHCONTENT_SOURCE_DIR_RMLUI=${DEPS:?set DEPS to your dependency checkout folder}/rmlui -DFETCHCONTENT_SOURCE_DIR_FREETYPE=${DEPS:?set DEPS to your dependency checkout folder}/freetype -DFETCHCONTENT_SOURCE_DIR_SQLITE3=${DEPS:?set DEPS to your dependency checkout folder}/npm-sqlite/package/deps/sqlite3 "$@"
